payload:
$ErrorActionPreference='Stop'
$repo = Join-Path $env:USERPROFILE 'mhw-pr230-sync2'
if (Test-Path $repo) { Remove-Item -Recurse -Force $repo }
git clone --quiet https://github.com/fengie/mhw-mods.git $repo
if ($LASTEXITCODE -ne 0) { throw "clone failed $LASTEXITCODE" }
git -C $repo checkout --quiet fix/heaven2-bridge-self-heal-20260929
if ($LASTEXITCODE -ne 0) { throw "checkout failed $LASTEXITCODE" }
git -C $repo fetch --quiet origin main
if ($LASTEXITCODE -ne 0) { throw "fetch main failed $LASTEXITCODE" }
git -C $repo merge --no-edit origin/main
if ($LASTEXITCODE -ne 0) {
  git -C $repo status --short
  git -C $repo diff --name-only --diff-filter=U
  git -C $repo merge --abort 2>$null
  throw "merge main failed"
}
git -C $repo push origin HEAD:fix/heaven2-bridge-self-heal-20260929
if ($LASTEXITCODE -ne 0) { throw "push failed $LASTEXITCODE" }
$head=(git -C $repo rev-parse HEAD).Trim()
$base=(git -C $repo rev-parse origin/main).Trim()
Write-Output "PR230_SYNC2_OK head=$head base=$base"
